import { FocusMonitor, FocusOrigin } from '@angular/cdk/a11y';
import { coerceCssPixelValue } from '@angular/cdk/coercion';
import { NgClass, NgIf, NgStyle, NgSwitch, NgSwitchCase, NgTemplateOutlet } from '@angular/common';
import {
  AfterViewInit,
  ChangeDetectionStrategy,
  ChangeDetectorRef,
  Component,
  DoCheck,
  ElementRef,
  EventEmitter,
  HostBinding,
  Injector,
  Input,
  NgZone,
  OnDestroy,
  OnInit,
  Output,
  TemplateRef,
  ViewChild,
  ViewEncapsulation,
  booleanAttribute,
  forwardRef,
  inject,
  numberAttribute,
} from '@angular/core';
import {
  ControlValueAccessor,
  FormGroupDirective,
  NG_VALUE_ACCESSOR,
  NgControl,
  NgForm,
  NgModel,
} from '@angular/forms';
import { QExpansionTriggerComponent } from '@questrade/allspark-angular-components/core/components';
import { QDestroyService } from '@questrade/allspark-angular-components/core/services';
import {
  ErrorState,
  randomString,
  voidFn,
} from '@questrade/allspark-angular-components/core/utils';
import {
  ErrorStateMatcher,
  ErrorStateMatcherInterface,
  FormFieldControl,
} from '@questrade/allspark-angular-components/form-control';
import { takeUntil } from 'rxjs';
import { QCheckboxContainerComponent } from './checkbox-container/checkbox-container.component';
import { QCheckboxExpandableComponent } from './checkbox-expandable/checkbox-expandable.component';
import { QCheckboxChange } from './types/checkbox-change.interface';
import { QCheckboxContainerDensity } from './types/checkbox-container-density.type';
import { QCheckboxExtraContentDensity } from './types/checkbox-extra-content-density.type';
import { QCheckboxExtraContentPosition } from './types/checkbox-extra-content-position.type';
import { QCheckboxLabelGap } from './types/checkbox-label-gap.type';
import { QCheckboxVariant } from './types/checkbox-variant.type';

enum TransitionCheckState {
  Init = 0,
  Checked = 1,
  Unchecked = 2,
  Indeterminate = 3,
}

@Component({
  imports: [
    NgIf,
    NgClass,
    NgStyle,
    NgTemplateOutlet,
    NgSwitch,
    NgSwitchCase,
    QCheckboxContainerComponent,
    QCheckboxExpandableComponent,
    QExpansionTriggerComponent,
  ],
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => QCheckboxComponent),
      multi: true,
    },
    { provide: FormFieldControl, useExisting: QCheckboxComponent },
    QDestroyService,
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-checkbox',
  templateUrl: './checkbox.component.html',
  styleUrls: ['./checkbox.component.scss'],
})
export class QCheckboxComponent
  extends ErrorState
  implements OnInit, AfterViewInit, DoCheck, OnDestroy, ControlValueAccessor
{
  @Output() readonly checkboxChange = new EventEmitter<QCheckboxChange>();
  @Output() readonly indeterminateChange = new EventEmitter<boolean>();
  @Output() readonly expandedChange = new EventEmitter<boolean>();

  @Input('aria-label') ariaLabel: string | null = null;
  @Input('aria-labelledby') ariaLabelledby: string | null = null;
  @Input('aria-describedby') ariaDescribedby: string | null = null;
  @Input() containerDensity: QCheckboxContainerDensity = 'default';
  @Input() extraContent: TemplateRef<unknown> | null = null;
  @Input() extraContentContext: unknown | null = null;
  @Input() extraContentDensity: QCheckboxExtraContentDensity = 'xs';
  @Input() extraContentPosition: QCheckboxExtraContentPosition = 'below';
  @Input() id = `q-checkbox-${randomString()}`;
  @Input() labelGap: QCheckboxLabelGap = 's';
  @Input() name: string | null = null;
  @Input() variant: QCheckboxVariant = 'default';
  @Input() override errorStateMatcher: ErrorStateMatcherInterface = new ErrorStateMatcher();
  @Input({ transform: booleanAttribute }) required = false;
  @Input({ transform: numberAttribute }) tabIndex = 0;
  @Input({ transform: coerceCssPixelValue }) extraContentRightWidth = '';
  @Input({ transform: booleanAttribute }) invalidState = false;
  @Input({ transform: booleanAttribute }) expanded = false;
  @Input({ transform: booleanAttribute }) readonly = false;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-checkbox';

  @Input({ transform: booleanAttribute }) get checked(): boolean {
    return this._checked;
  }
  set checked(value: boolean) {
    if (value != this.checked) {
      this._checked = value;
      this._cdr.markForCheck();
    }
  }

  @Input({ transform: booleanAttribute }) get indeterminate(): boolean {
    return this._indeterminate;
  }
  set indeterminate(value: boolean) {
    const changed = value != this._indeterminate;
    this._indeterminate = value;
    if (changed) {
      this._handleIndeterminateChanged();
    }
    this._syncIndeterminate(this._indeterminate);
  }

  @Input({ transform: booleanAttribute }) get disabled(): boolean {
    return this._disabled;
  }
  set disabled(value: boolean) {
    if (value !== this.disabled) {
      this._disabled = value;
      this._cdr.markForCheck();
    }
  }

  @ViewChild('inputRef') _inputElement!: ElementRef<HTMLInputElement>;
  @ViewChild(QCheckboxExpandableComponent) _checkboxExpandable!: QCheckboxExpandableComponent;

  // Clears any attribute added by mistake to the host element
  @HostBinding('attr.tabindex') _hostTabIndex: string | null = null;
  @HostBinding('attr.aria-label') _hostAriaLabel: string | null = null;
  @HostBinding('attr.aria-labelledby') _hostAriaLabelledBy: string | null = null;
  @HostBinding('attr.aria-describedby') _hostAriaDescribedBy: string | null = null;
  @HostBinding('attr.id') _hostId = this.id;

  @HostBinding('class') get hostClassNames(): string {
    return [
      'q-checkbox',
      `q-checkbox-variant-${this.variant}`,
      `q-checkbox-container-density-${this.containerDensity}`,
      this.checked && 'q-checkbox-checked',
      this.disabled && 'q-checkbox-disabled',
      this.readonly && 'q-checkbox-readonly',
      this.invalidState && 'q-checkbox-invalid',
      this.indeterminate && 'q-checkbox-indeterminate',
    ]
      .filter(Boolean)
      .join(' ');
  }

  _controlValueAccessorChangeFn: (value: unknown) => void = voidFn;
  _onTouched: () => unknown = voidFn;

  private _currentAnimationClass = '';
  private _currentCheckState = TransitionCheckState.Init;
  private _disabled = false;
  private _checked = false;
  private _indeterminate = false;
  private readonly _injector = inject(Injector);
  private readonly _cdr = inject(ChangeDetectorRef);
  private readonly _ngZone = inject(NgZone);
  private readonly _focusMonitor = inject(FocusMonitor);
  private readonly _destroy$ = inject(QDestroyService);
  readonly _elementRef = inject(ElementRef);

  constructor() {
    super(inject(FormGroupDirective, { optional: true }), inject(NgForm, { optional: true }));
  }

  ngOnInit(): void {
    this._setComponentControl();
  }

  ngDoCheck(): void {
    if (this.ngControl) {
      this._updateErrorState();

      if (!(this.ngControl instanceof NgModel)) {
        this.invalidState = this.errorState;
      }
    }
  }

  ngAfterViewInit(): void {
    this._syncIndeterminate(this._indeterminate);

    this._focusMonitor
      .monitor(this._elementRef, true)
      .pipe(takeUntil(this._destroy$))
      .subscribe({
        next: (focusOrigin: FocusOrigin) => {
          if (!focusOrigin) {
            this._onBlur();
          }
        },
      });
  }

  ngOnDestroy(): void {
    this._focusMonitor.stopMonitoring(this._elementRef);
  }

  _onLabelInteraction(): void {
    if (this.variant === 'expandable' && !this.disabled && !this.readonly) {
      this._checkboxExpandable.toggle();
    }
  }

  _onExpandedChange(expanded: boolean): void {
    this.expanded = expanded;
    this.expandedChange.emit(expanded);
  }

  _onCheckboxContainerChange(event: Event): void {
    if (this.variant === 'container') {
      this._onInputInteraction(event);
    }
  }

  _onTouchTargetClick(event: Event): void {
    if (this.variant === 'expandable') {
      return;
    }

    this._onInputInteraction(event);

    if (!this.disabled) {
      this._inputElement.nativeElement.focus();
    }
  }

  _onChangeEvent(event: Event): void {
    event.stopPropagation();

    if (this.variant === 'expandable') {
      this._onInputInteraction(event);
    }
  }

  _onInputInteraction(event: Event): void {
    event.stopPropagation();

    if (!this.disabled && !this.readonly) {
      if (this.indeterminate) {
        this._indeterminate = false;
        this.indeterminateChange.emit(this._indeterminate);
      }

      this._checked = !this._checked;
      this._transitionCheckState(
        this._checked ? TransitionCheckState.Checked : TransitionCheckState.Unchecked,
      );
      this._emitChangeEvent();
    }
  }

  _onBlur(): void {
    this._onTouched();
    this._cdr.detectChanges();
  }

  /** @hidden */
  writeValue(value: unknown): void {
    this.checked = !!value;
  }

  /** @hidden */
  registerOnChange(fn: (value: unknown) => void): void {
    this._controlValueAccessorChangeFn = fn;
  }

  /** @hidden */
  registerOnTouched(fn: () => unknown): void {
    this._onTouched = fn;
  }

  /** @hidden */
  setDisabledState(isDisabled: boolean): void {
    this.disabled = isDisabled;
  }

  get canRenderExtraContentBelow(): boolean {
    return (
      this.variant === 'default' && this.extraContentPosition === 'below' && !!this.extraContent
    );
  }

  get canRenderExtraContentRight(): boolean {
    return (
      this.variant === 'container' && this.extraContentPosition === 'right' && !!this.extraContent
    );
  }

  private _handleIndeterminateChanged(): void {
    if (this._indeterminate) {
      this._transitionCheckState(TransitionCheckState.Indeterminate);
    } else {
      this._transitionCheckState(
        this.checked ? TransitionCheckState.Checked : TransitionCheckState.Unchecked,
      );
    }
    this.indeterminateChange.emit(this._indeterminate);
  }

  private _transitionCheckState(newState: TransitionCheckState): void {
    const oldState = this._currentCheckState;
    const element: HTMLElement = this._elementRef.nativeElement;
    if (oldState === newState) {
      return;
    }
    if (this._currentAnimationClass.length > 0) {
      element.classList.remove(this._currentAnimationClass);
    }
    this._currentAnimationClass = this._getAnimationClassForCheckStateTransition(
      oldState,
      newState,
    );
    this._currentCheckState = newState;
    if (this._currentAnimationClass.length > 0) {
      element.classList.add(this._currentAnimationClass);
      const animationClass = this._currentAnimationClass;
      this._ngZone.runOutsideAngular(() => {
        setTimeout(() => {
          element.classList.remove(animationClass);
        }, 1000);
      });
    }
  }

  private _getAnimationClassForCheckStateTransition(
    oldState: TransitionCheckState,
    newState: TransitionCheckState,
  ): string {
    let animSuffix = '';

    switch (oldState) {
      case TransitionCheckState.Init:
        if (newState === TransitionCheckState.Checked) {
          animSuffix = 'unchecked-checked';
        } else if (newState == TransitionCheckState.Indeterminate) {
          animSuffix = 'unchecked-indeterminate';
        } else {
          return '';
        }
        break;

      case TransitionCheckState.Unchecked:
        animSuffix =
          newState === TransitionCheckState.Checked
            ? 'unchecked-checked'
            : 'unchecked-indeterminate';
        break;

      case TransitionCheckState.Checked:
        animSuffix =
          newState === TransitionCheckState.Unchecked
            ? 'checked-unchecked'
            : 'checked-indeterminate';
        break;

      case TransitionCheckState.Indeterminate:
        animSuffix =
          newState === TransitionCheckState.Checked
            ? 'indeterminate-checked'
            : 'indeterminate-unchecked';
        break;
    }

    return `q-checkbox-anim-${animSuffix}`;
  }

  private _emitChangeEvent(): void {
    this._controlValueAccessorChangeFn(this.checked);
    this.checkboxChange.emit({ checked: this.checked, source: this, target: this._elementRef });

    if (this._inputElement) {
      this._inputElement.nativeElement.checked = this.checked;
    }
  }

  private _syncIndeterminate(value: boolean): void {
    const nativeCheckbox = this._inputElement;

    if (nativeCheckbox) {
      nativeCheckbox.nativeElement.indeterminate = value;
    }
  }

  private _setComponentControl(): void {
    const injectedControl = this._injector.get(NgControl, null);

    if (injectedControl) {
      this.ngControl = injectedControl;
    }
  }
}
