import {
  ChangeDetectionStrategy,
  Component,
  HostBinding,
  Input,
  ViewEncapsulation,
} from '@angular/core';
import { QLineClampDirective } from '@questrade/allspark-angular-components/core/directives';
import { QCheckboxLabelColor } from '../types/checkbox-label-color.type';
import { QCheckboxLabelTypography } from '../types/checkbox-label-typography.type';

@Component({
  hostDirectives: [{ directive: QLineClampDirective, inputs: ['lineClamp'] }],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  selector: 'q-checkbox-label',
  template: `<ng-content />`,
  styleUrls: ['./checkbox-label.component.scss'],
})
export class QCheckboxLabelComponent {
  @Input() labelTypography: QCheckboxLabelTypography = 'body-m';
  @Input() labelColor: QCheckboxLabelColor = 'grey-primary';
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-checkbox-label';

  @HostBinding('class') get hostClass(): string {
    return [
      'q-checkbox-label',
      `q-${this.labelTypography}`,
      `q-checkbox-label-color-${this.labelColor}`,
    ].join(' ');
  }
}
