import { NgClass, NgIf, NgTemplateOutlet } from '@angular/common';
import {
  ChangeDetectionStrategy,
  Component,
  EventEmitter,
  HostBinding,
  Input,
  OnChanges,
  Output,
  SimpleChanges,
  TemplateRef,
  ViewEncapsulation,
  booleanAttribute,
} from '@angular/core';
import { accordionAnimations } from '@questrade/allspark-angular-components/core/animations';
import { QCheckboxExtraContentDensity } from '../types/checkbox-extra-content-density.type';
import { QCheckboxExtraContentPosition } from '../types/checkbox-extra-content-position.type';
import { QCheckboxVariant } from '../types/checkbox-variant.type';

@Component({
  imports: [NgIf, NgClass, NgTemplateOutlet],
  changeDetection: ChangeDetectionStrategy.OnPush,
  encapsulation: ViewEncapsulation.None,
  animations: [accordionAnimations.bodyExpansion],
  selector: 'q-checkbox-container',
  templateUrl: './checkbox-container.component.html',
  styleUrls: ['./checkbox-container.component.scss'],
})
export class QCheckboxContainerComponent implements OnChanges {
  @Output() readonly checkboxContainerChange = new EventEmitter<Event>();

  @Input({ transform: booleanAttribute }) expanded = false;
  @Input() extraContent: TemplateRef<unknown> | null = null;
  @Input() extraContentContext: unknown | null = null;
  @Input() extraContentDensity: QCheckboxExtraContentDensity = 'xs';
  @Input() extraContentPosition: QCheckboxExtraContentPosition = 'below';
  @Input() variant!: QCheckboxVariant;
  @Input() disabled!: boolean;
  @Input() checkboxInputId!: string;
  @Input() @HostBinding('attr.data-qt') dataQt = 'q-checkbox-container';

  ngOnChanges(changes: SimpleChanges): void {
    const { disabled } = changes || {};

    if (disabled?.currentValue) {
      this.expanded = false;
    }
  }

  _onContainerInteraction(event: Event): void {
    this.checkboxContainerChange.emit(event);
  }
}
